from moler.device import DeviceFactory
from taf.config.testline.airscale import CommonUnit, CapacityUnit
from taf.config.testline.gnb import ClassicalBts, DU
from taf.config.testline.radio import RU
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.utilities.robot.general import get_builtin_value
from taf.rfrl.utilities.moler.custom_device_factory import add_namespace_state_for_device
from taf.rfrl.utilities.logger.custom_logger import log_info_to_console
from taf.ul.moler.converter.interface import get_devices_from_regex
from taf.ul.moler.converter.moler_converter import MolerConverter


@load_moler_configuration_from_tl()
def create_namespaces_for_devices(devices=None, source_state="PROXY_PC", dest_state="RU",
                                  create_namespace_function=None, interface_type="lmp"):
    """
    :param devices: list with name of moler devices with namespace name and namespace interface, that wil be created ex:
                    [{"GNB0_DU0_RU0_LMP": {"namespace_name": name, "namespace_interface": interface}}]
    :param source_state: state from which we want to hop to namespace
    :param dest_state: state to which we want to hop from namespace
    :param create_namespace_function: can be defined to custom function that will create namespace
    :param interface_type: type of interface that will be used to check if namespaces is needed
    """

    tl = get_builtin_value(param_name="tl")
    all_connections = []
    for test_pc in tl.test_pcs:
        try:
            connections = test_pc.connections
            all_connections.extend(connections)
        except AttributeError:
            pass
    if not all_connections:
        raise AttributeError("Connections in testpcs not found!")

    namespace_connections = NetworkNamespace.check_if_namespaces_are_needed(all_connections, interface_type)
    if namespace_connections is False:
        return None

    if create_namespace_function is None:
        create_namespace_function = NetworkNamespace.create_namespace_for_device_lmp
    if devices is None:
        devices = NetworkNamespace.get_device_names_from_test_pc_connections(all_connections)
    for device, values in devices.items():
        moler_device = DeviceFactory.get_device(device, initial_state=source_state)
        if NetworkNamespace.check_if_namespace_already_created(moler_device, values["namespace_name"]) is True:
            log_info_to_console("Namespace {} already created".format(values["namespace_name"]))
            continue
        log_info_to_console("Creating namespace for device {}".format(device))
        create_namespace_function(moler_device, values["namespace_name"], values["namespace_interface"])

    custom_moler_devices = []
    for device, values in devices.items():
        new_device_name = device + "_NAMESPACE"
        custom_device = add_namespace_state_for_device(device, dest_state=dest_state, new_device_name=new_device_name,
                                                       namespace_name=values["namespace_name"])
        custom_moler_devices.append(custom_device.device)
    return custom_moler_devices


class NetworkNamespace:
    excluded_interfaces = ["eth0", "eth1"]
    moler_subdevices_mapping = {ClassicalBts: "GNB", DU: "DU", RU: "RU", CommonUnit: "CU", CapacityUnit: "CPTY"}
    connections_types = ["LMP"]

    @staticmethod
    @load_moler_configuration_from_tl()
    def get_device_names_from_test_pc_connections(connections):
        devices = NetworkNamespace.create_info_dict_from_connections(connections)
        for device, values in dict(devices).items():
            if values["namespace_interface"] in NetworkNamespace.excluded_interfaces:
                del devices[device]
        tl = get_builtin_value(param_name="tl")
        gnb_ru_info = MolerConverter()._get_gnb_and_ru(tl)
        for connection in gnb_ru_info:
            for itt, device in enumerate(connection):
                if device in devices.keys():
                    device_name = NetworkNamespace.reverse_device_name(connection[:itt + 1])
                    moler_device_names = get_devices_from_regex(r"{}_.*".format(device_name))
                    if len(moler_device_names) > 1:
                        moler_device_names = [moler_device for moler_device in moler_device_names
                                              if any(postfix in moler_device for postfix in
                                                     NetworkNamespace.connections_types)]
                    device_name = moler_device_names[0]
                    devices[device_name] = devices.pop(device)
        return devices

    @staticmethod
    def create_info_dict_from_connections(connections):
        info_dict = {}
        for connection in connections:
            namespace_name, namespace_interface = NetworkNamespace.get_namespace_name_and_interface_from_connection(
                connection)
            info_dict[connection.device] = {"namespace_name": namespace_name,
                                            "namespace_interface": namespace_interface}
        return info_dict

    @staticmethod
    def get_namespace_name_and_interface_from_connection(connection):
        interface = connection.interface.split("::")
        if len(interface) > 1:
            namespace_name = interface[1]
        else:
            namespace_name = connection.device.serial_number
        namespace_interface = interface[0]
        return namespace_name, namespace_interface

    @staticmethod
    def reverse_device_name(connection):
        device_name = []
        for device_id, device in zip(connection[:-1], connection[1:]):
            device_type = type(device)
            if device_type in NetworkNamespace.moler_subdevices_mapping:
                device_name.append("{}{}".format(NetworkNamespace.moler_subdevices_mapping[device_type], device_id))
        return "_".join(device_name)

    @staticmethod
    def check_if_namespaces_are_needed(connections, interface_type):
        namespace_connections = []
        for connection in connections:
            if connection.interface_type == interface_type:
                namespace_connections.append(connection)
        if len(namespace_connections) > 1:
            return namespace_connections
        return False

    @staticmethod
    def create_namespace_for_device_lmp(device, namespace_name=None, namespace_interface=None):
        command = "sudo ip netns add {}".format(namespace_name)
        device.get_cmd(cmd_name="run_script", cmd_params={'script_command': command})()
        command = "sudo ip link add veth{} type veth peer name {}".format(namespace_name, namespace_interface)
        device.get_cmd(cmd_name="run_script", cmd_params={'script_command': command})()
        command = "sudo ip link set {} netns {}".format(namespace_interface, namespace_name)
        device.get_cmd(cmd_name="run_script", cmd_params={'script_command': command})()
        command = "sudo ip netns exec {} ip addr add 192.168.255.126/24 brd 192.168.255.255 scope global dev {}" \
            .format(namespace_name, namespace_interface)
        device.get_cmd(cmd_name="run_script", cmd_params={'script_command': command})()
        command = "sudo ip netns exec {} ip link set dev {} up".format(namespace_name, namespace_interface)
        device.get_cmd(cmd_name="run_script", cmd_params={'script_command': command})()

    @staticmethod
    def get_namespace_list(device):
        command = "sudo ip netns list  > /tmp/namespaces.txt"
        device.get_cmd(cmd_name="run_script", cmd_params={'script_command': command})()
        namespaces = device.get_cmd(cmd_name="cat", cmd_params={'path': "/tmp/namespaces.txt"})()
        return namespaces["LINES"]

    @staticmethod
    def check_if_namespace_already_created(device, namespace_name):
        return namespace_name in [namespace.split(" ")[0] for namespace in NetworkNamespace.get_namespace_list(device)]
